<template>
  <div class="month-view">
    <div class="large-calendar">
      <div class="month-watermark">
        {{ currentYear }}年 {{ currentMonth }}月
      </div>
      <div class="weekdays-large">
        <div v-for="day in weekdays" :key="day" class="weekday-large">
          {{ day }}
        </div>
      </div>
      <div class="days-large">
        <el-tooltip
          v-for="(day, index) in getMonthDays(currentMonth)"
          :key="index"
          :content="day ? getDayEventNames(currentYear, currentMonth, day) : ''"
          placement="top"
          effect="dark"
          :disabled="!day || !hasColor(currentYear, currentMonth, day)"
        >
          <div
            :class="[
              'day-cell-large',
              { empty: !day, clickable: day, colored: day && hasColor(currentYear, currentMonth, day) }
            ]"
            :style="day ? getDayStyle(currentYear, currentMonth, day) : {}"
            @click="day && emit('toggle-day-event', currentYear, currentMonth, day)"
          >
            <span class="day-number">{{ day || '' }}</span>
          </div>
        </el-tooltip>
      </div>
    </div>
  </div>
</template>

<script setup>
import { defineEmits, defineProps } from 'vue'

const weekdays = ['日', '一', '二', '三', '四', '五', '六']

defineProps({
  currentYear: {
    type: Number,
    required: true
  },
  currentMonth: {
    type: Number,
    required: true
  },
  getMonthDays: {
    type: Function,
    required: true
  },
  getDayEventNames: {
    type: Function,
    required: true
  },
  hasColor: {
    type: Function,
    required: true
  },
  getDayStyle: {
    type: Function,
    required: true
  }
})

const emit = defineEmits(['toggle-day-event'])
</script>
